  ('84dada2f-d28f-4eec-8fb5-28b459361b6b'::uuid, $pea0$Que sí, se suman los dos descuentos.$pea0$, false, 1, $pea0$Becas y beneficios no son acumulables entre sí.$pea0$, null::int, null),
