  ('8a3aeb53-6c65-448f-854d-44f8035ddfd7'::uuid, $pea0$Que es normal: el Seminario Final se pierde con el pase.$pea0$, false, 1, $pea0$El Seminario Final regular se mantiene en todos los casos.$pea0$, null::int, null),
