  ('773ee852-9985-481c-88ab-425539e003bb'::uuid, $pea0$Verdadero$pea0$, false, 1, null, null::int, null),
  ('9cc20443-acc2-4f57-8c47-598567b11fde'::uuid, $pea0$Falso$pea0$, true, 2, null, null::int, null)
